html[data-slaidy-theme="educanet"]{
 --th-navy:#0D1140;--th-ink:#0D1140;--th-text:#232750;--th-muted:#6B7085;
 --th-teal:#009AB1;--th-teal-web:#01A8BA;--th-teal-ink:#007A8C;--th-teal-wash:#E5F5F7;
 --th-orange:#EB5D0B;--th-yellow:#FBB900;--th-gray:#A4ADB5;
 --th-line:#E1E3EA;--th-row:#F4F5F8;--th-wash:#EEF0F5;
 --th-font:"Exo 2",system-ui,sans-serif;
 --th-bar:linear-gradient(90deg,var(--th-teal) 0 33.3%,var(--th-orange) 33.3% 66.6%,var(--th-yellow) 66.6% 100%);
 --th-squares:
  linear-gradient(var(--th-orange),var(--th-orange)) right 104px top 268px/44px 44px no-repeat,
  linear-gradient(var(--th-yellow),var(--th-yellow)) right 104px top 330px/44px 44px no-repeat,
  linear-gradient(var(--th-teal),var(--th-teal)) right 104px top 392px/44px 44px no-repeat;
}

/* ---------- content slides: white, navy type, the logo's three colours as a bar ---------- */
html[data-slaidy-theme="educanet"] .stage{background:#fff;color:var(--th-ink);padding:44px 72px 84px;
 font-family:var(--th-font);-webkit-print-color-adjust:exact;print-color-adjust:exact}
html[data-slaidy-theme="educanet"] .stage h2{font-family:var(--th-font);font-weight:800;color:var(--th-ink);
 letter-spacing:-.01em;line-height:1.1;margin-bottom:22px}
html[data-slaidy-theme="educanet"] .stage h2::after{content:"";display:block;width:84px;height:5px;margin-top:14px;
 background:var(--th-bar);border-radius:1px}
html[data-slaidy-theme="educanet"] .stage .tx{font-family:var(--th-font);font-weight:400;color:var(--th-text);line-height:1.42}
html[data-slaidy-theme="educanet"] .stage .tx b,html[data-slaidy-theme="educanet"] .stage .tx strong{font-weight:700;color:var(--th-ink)}
html[data-slaidy-theme="educanet"] .stage .tx li::marker{color:var(--th-teal);font-weight:700}
html[data-slaidy-theme="educanet"] .stage .tx .bh{font-family:var(--th-font);font-weight:800;color:var(--th-ink)}
html[data-slaidy-theme="educanet"] .stage .tx h4.bh{font-weight:700;color:var(--th-teal-ink);letter-spacing:.08em;
 text-transform:uppercase;font-size:.72em}
html[data-slaidy-theme="educanet"] .stage .tx blockquote{background:var(--th-teal-wash);border-left:6px solid var(--th-teal);
 border-radius:0 14px 14px 0;padding:.45em .9em;margin:.55em 0;color:var(--th-ink);font-weight:700;font-size:1.06em}
html[data-slaidy-theme="educanet"] .stage .tx blockquote p:last-child{margin-bottom:0}
html[data-slaidy-theme="educanet"] .stage .tx a{color:var(--th-teal-ink);text-decoration:underline;
 text-decoration-thickness:1.5px;text-underline-offset:3px}
html[data-slaidy-theme="educanet"] .stage .tx code{background:var(--th-wash);color:var(--th-ink);border:0;border-radius:4px;
 padding:.08em .32em;font-size:.86em}
html[data-slaidy-theme="educanet"] .stage .tx pre{background:var(--th-wash);border:0;border-left:4px solid var(--th-teal);
 border-radius:0 8px 8px 0}
html[data-slaidy-theme="educanet"] .stage .tx pre code{background:none;padding:0}
html[data-slaidy-theme="educanet"] .stage .tx .rule{border-top:2px solid var(--th-line)}
/* tables: a navy band, quiet zebra rows */
html[data-slaidy-theme="educanet"] .stage .tx table{border-collapse:separate;border-spacing:0;font-size:.86em;line-height:1.3}
html[data-slaidy-theme="educanet"] .stage .tx th{background:var(--th-navy);color:#fff;font-family:var(--th-font);font-weight:700;
 text-transform:none;letter-spacing:0;font-size:.92em;padding:8px 12px;border:0;vertical-align:bottom}
html[data-slaidy-theme="educanet"] .stage .tx th:first-child{border-top-left-radius:10px}
html[data-slaidy-theme="educanet"] .stage .tx th:last-child{border-top-right-radius:10px}
html[data-slaidy-theme="educanet"] .stage .tx td{padding:6px 12px;border:0;border-bottom:1px solid var(--th-line)}
html[data-slaidy-theme="educanet"] .stage .tx tbody tr:nth-child(even) td{background:var(--th-row)}

/* footer: the header row moved to the bottom — logo · the deck's footer line · n / total */
html[data-slaidy-theme="educanet"] .stage .hdr{position:absolute;left:72px;right:72px;bottom:22px;margin:0;height:40px;
 align-items:center;gap:18px;text-transform:none;letter-spacing:0;font:400 17px/1 var(--th-font);color:var(--th-muted)}
html[data-slaidy-theme="educanet"] .stage .hdr::before{content:"";flex:none;width:84px;height:40px;
 background:url(data:image/png;base64,) left center/contain no-repeat}
html[data-slaidy-theme="educanet"] .stage .hdr .hpath{flex:1;font-size:0;color:var(--th-muted)}
html[data-slaidy-theme="educanet"] .stage .hdr .hpath::before{content:var(--slaidy-footer,"");font:400 17px/1 var(--th-font);
 padding-left:18px;border-left:1.5px solid var(--th-line)}
html[data-slaidy-theme="educanet"] .stage .hdr .pos{display:none}
html[data-slaidy-theme="educanet"] .stage .hdr .ix:not(:empty){color:var(--th-navy);font:700 15px/1 var(--th-font);
 border:1.5px solid var(--th-navy);border-radius:999px;padding:7px 13px 8px}

/* ---------- cover & closing: navy like the school's web, white logo, the three squares ---------- */
html[data-slaidy-theme="educanet"] .stage.lay-cover,html[data-slaidy-theme="educanet"] .stage.lay-closing{
 background:var(--th-squares),var(--th-navy);color:#fff;padding:228px 96px 64px}
html[data-slaidy-theme="educanet"] .stage.lay-cover::before,html[data-slaidy-theme="educanet"] .stage.lay-closing::before{content:"";
 position:absolute;left:96px;top:52px;width:150px;height:86px;background:url(data:image/png;base64,) left center/contain no-repeat}
html[data-slaidy-theme="educanet"] .stage.lay-cover h2,html[data-slaidy-theme="educanet"] .stage.lay-closing h2{color:#fff;
 font-weight:800;max-width:76%;letter-spacing:-.015em}
html[data-slaidy-theme="educanet"] .stage.lay-cover h2.big{font-size:calc(var(--d-title)*1.5)}
html[data-slaidy-theme="educanet"] .stage.lay-closing h2.big{font-size:calc(var(--d-title)*1.3)}
html[data-slaidy-theme="educanet"] .stage.lay-cover h2::after,html[data-slaidy-theme="educanet"] .stage.lay-closing h2::after{
 width:132px;height:6px;margin-top:22px}
html[data-slaidy-theme="educanet"] .stage.lay-cover .tx,html[data-slaidy-theme="educanet"] .stage.lay-closing .tx{
 color:rgba(255,255,255,.86);max-width:64%;font-size:calc(var(--d-body)*.9);line-height:1.35}
html[data-slaidy-theme="educanet"] .stage.lay-cover .tx b,html[data-slaidy-theme="educanet"] .stage.lay-cover .tx strong,
html[data-slaidy-theme="educanet"] .stage.lay-closing .tx b,html[data-slaidy-theme="educanet"] .stage.lay-closing .tx strong,
html[data-slaidy-theme="educanet"] .stage.lay-cover .tx .bh,html[data-slaidy-theme="educanet"] .stage.lay-closing .tx .bh{color:#fff}
html[data-slaidy-theme="educanet"] .stage.lay-cover .tx a,html[data-slaidy-theme="educanet"] .stage.lay-closing .tx a{color:#fff}
html[data-slaidy-theme="educanet"] .stage.lay-cover .tx li::marker,html[data-slaidy-theme="educanet"] .stage.lay-closing .tx li::marker{color:var(--th-teal-web)}
html[data-slaidy-theme="educanet"] .stage.lay-cover .tx blockquote,html[data-slaidy-theme="educanet"] .stage.lay-closing .tx blockquote{
 background:none;border:0;padding:0;color:#fff;font-weight:700;font-size:1.25em}
html[data-slaidy-theme="educanet"] .stage.lay-cover .hdr,html[data-slaidy-theme="educanet"] .stage.lay-closing .hdr{display:none}
